sksl:
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float time;
uniform float blockSize;
uniform float2 stretch;
uniform float strength;
uniform float mono;
uniform float freeze;
uniform float extremes;
uniform float2 offset;
uniform float overshoot;
uniform float seed;
float hash13(float3 p) {
    p = fract(p * 0.1031);
    p += dot(p, p.zyx + 31.32);
    return fract((p.x + p.y) * p.z);
}
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return src;
    float2 dims = max(abs(stretch), float2(0.01)) * max(blockSize, 1.0) * layer / 150.0;
    float2 n = floor((coord - size * 0.5 - offset) / dims);
    float frame = freeze > 0.5 ? 0.0 : floor(time * 24.0);
    float3 k = float3(n, frame + seed * 101.0);
    float3 v = float3(hash13(k), hash13(k + 19.7), hash13(k + 41.3));
    if (mono > 0.5) v = v.xxx;
    if (extremes > 0.5) v = step(0.5, v);
    float3 base = float3(src.rgb) / float(src.a);
    float3 rgb = clamp(base + (v - 0.5) * overshoot * clamp(strength, 0.0, 1.0), 0.0, 1.0);
    return half4(half3(rgb) * src.a, src.a);
}
